CREATE OR REPLACE FUNCTION public.ensure_grade5_signup_student(p_full_name text)
 RETURNS students
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_parent_id uuid := auth.uid();
  v_student public.students;
begin
  if v_parent_id is null then
    raise exception 'authentication required';
  end if;

  if nullif(btrim(p_full_name), '') is null then
    raise exception 'student name required';
  end if;

  select * into v_student
  from public.students
  where parent_id = v_parent_id
  order by created_at asc
  limit 1;

  if found then
    return v_student;
  end if;

  insert into public.students (parent_id, full_name, grade_level, creation_source)
  values (v_parent_id, btrim(p_full_name), 5, 'grade5_signup')
  on conflict (parent_id) where creation_source = 'grade5_signup'
  do update set full_name = public.students.full_name
  returning * into v_student;

  return v_student;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_grade5_signup_student_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_caller_id uuid := (select auth.uid());
  v_signup_child text;
begin
  if v_caller_id is null or new.parent_id is distinct from v_caller_id then
    raise exception 'Student ownership verification failed' using errcode = '42501';
  end if;

  if new.grade_level = 5 and new.creation_source is null then
    select nullif(pg_catalog.btrim(u.raw_user_meta_data ->> 'child_name'), '')
      into v_signup_child
      from auth.users u
     where u.id = v_caller_id
       and u.id = new.parent_id
       and u.email_confirmed_at is not null;

    if v_signup_child is not null
       and pg_catalog.lower(pg_catalog.btrim(new.full_name)) = pg_catalog.lower(v_signup_child)
       and not exists (
         select 1
           from public.students s
          where s.parent_id = new.parent_id
            and s.creation_source = 'grade5_signup'
       ) then
      new.creation_source := 'grade5_signup';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_student_creation_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.creation_idempotency_key is distinct from old.creation_idempotency_key then
    raise exception 'Student creation identity is immutable' using errcode = '42501';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.add_grade5_student(p_full_name text, p_idempotency_key uuid)
 RETURNS students
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_caller_id uuid := (select auth.uid());
  v_student_name text := pg_catalog.btrim(p_full_name);
  v_subscription_id uuid;
  v_allowance integer;
  v_student_count integer;
  v_existing public.students%rowtype;
  v_created public.students%rowtype;
begin
  if v_caller_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  if not exists (
    select 1
      from public.profiles p
     where p.id = v_caller_id
       and p.role = 'parent'
  ) then
    raise exception 'Parent account required' using errcode = '42501';
  end if;

  if p_idempotency_key is null then
    raise exception 'Student operation identity required' using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_caller_id::text || ':grade5:students', 0)
  );

  -- Only the caller-scoped operation key identifies a retry. Names are not
  -- identities: a fresh operation key may intentionally create a namesake.
  select s.*
    into v_existing
    from public.students s
   where s.parent_id = v_caller_id
     and s.creation_idempotency_key = p_idempotency_key;

  if found then
    if v_existing.full_name is distinct from v_student_name then
      raise exception 'Student operation payload conflict' using errcode = '22000';
    end if;
    return v_existing;
  end if;

  if v_student_name is null or v_student_name = '' then
    raise exception 'Student name required' using errcode = '22023';
  end if;

  select s.id, least(s.max_students, c.max_students)
    into v_subscription_id, v_allowance
    from public.subscriptions s
    join public.grade5_plan_configuration c on c.code = s.plan_code
   where s.parent_id = v_caller_id
     and s.grade = 'grade5'
     and s.status = 'active'
     and (s.starts_at is null or s.starts_at <= pg_catalog.clock_timestamp())
     and s.expires_at > pg_catalog.clock_timestamp()
   order by s.starts_at desc nulls last, s.expires_at desc, s.id
   limit 1;

  if v_subscription_id is null then
    select c.max_students
      into v_allowance
      from public.grade5_plan_configuration c
     where c.code = 'free';
    v_allowance := coalesce(v_allowance, 1);
  end if;

  select pg_catalog.count(*)::integer
    into v_student_count
    from public.students s
   where s.parent_id = v_caller_id
     and s.grade_level = 5;

  if v_student_count >= v_allowance then
    raise exception 'Student capacity reached' using errcode = 'P0001';
  end if;

  insert into public.students
    (parent_id, subscription_id, full_name, grade_level, creation_idempotency_key)
  values
    (v_caller_id, v_subscription_id, v_student_name, 5, p_idempotency_key)
  returning * into v_created;

  return v_created;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.protect_grade5_cash_payment_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if old.method = 'cash' and (
    new.offline_reference is distinct from old.offline_reference
    or new.reference_code is distinct from old.reference_code
    or new.offline_idempotency_key is distinct from old.offline_idempotency_key
    or new.cash_business_date is distinct from old.cash_business_date
  ) then
    raise exception 'Cash payment identity is immutable' using errcode = '22000';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.register_grade5_cash_payment_reference()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.grade = 'grade5' and new.method = 'cash' and new.offline_reference is not null then
    insert into public.grade5_cash_reference_registry
      (reference_key, reference_value, source_type, source_id)
    values (lower(new.offline_reference), new.offline_reference, 'payment', new.id)
    on conflict (reference_key) do nothing;

    if not exists (
      select 1 from public.grade5_cash_reference_registry r
      where r.reference_key = lower(new.offline_reference)
        and r.source_type = 'payment'
        and r.source_id = new.id
    ) then
      raise exception 'Cash reference collision' using errcode = '23505';
    end if;
  end if;
  return new;
end;
$function$
